steps.action_code:
def normalize_alarm_label(value):
    return " ".join(
        "".join(character.lower() if character.isalnum() else " " for character in value).split()
    )

target_label = normalize_alarm_label("go-to-sleep")
target_alarm_candidates = [
    alarm for alarm in alarms_before_updates
    if normalize_alarm_label(alarm.get("label", "")) == target_label
]
if len(target_alarm_candidates) != 1:
    raise RuntimeError("Expected exactly one alarm whose normalized label is go to sleep")
target_alarm = target_alarm_candidates[0]
target_alarm_id = target_alarm["alarm_id"]
time_parts = target_alarm["time"].split(":")
if len(time_parts) != 2:
    raise RuntimeError("Target alarm time is not in HH:MM format")
target_hour = int(time_parts[0])
target_minute = int(time_parts[1])
if not (0 <= target_hour <= 23 and 0 <= target_minute <= 59):
    raise RuntimeError("Target alarm time is outside the valid HH:MM range")
new_target_time = f"{(target_hour + 1) % 24:02d}:{target_minute:02d}"
print({
    "target_alarm_id": target_alarm_id,
    "label": target_alarm["label"],
    "current_time": target_alarm["time"],
    "reviewed_new_time": new_target_time,
})

disable_alarm_plan = [
    {"alarm_id": alarm["alarm_id"], "enabled": False}
    for alarm in alarms_after_time_update
    if alarm["alarm_id"] != target_alarm_id and alarm["enabled"]
]
other_alarm_count = sum(
    1 for alarm in alarms_after_time_update
    if alarm["alarm_id"] != target_alarm_id
)
already_disabled_other_count = other_alarm_count - len(disable_alarm_plan)
print({
    "target_alarm_id_excluded": target_alarm_id,
    "disable_alarm_ids": [item["alarm_id"] for item in disable_alarm_plan],
    "already_disabled_other_count": already_disabled_other_count,
})

disable_update_responses = []
for disable_item in disable_alarm_plan:
    disable_update_responses.append(
        apis.phone.update_alarm(
            alarm_id=disable_item["alarm_id"],
            access_token=phone_access_token,
            enabled=disable_item["enabled"],
        )
    )
